void InstallGeneratedHooks() {
	for (const RegDesc& r : kRegs) {
		if (!r.rva) continue;
		uint8_t* p = (uint8_t*)(Runtime::GameCoreAddress + r.rva);
		if (memcmp(p, r.prologue, 8) != 0) { Log("[DevBridge] registration function of %s has unexpected bytes: its methods are not added", r.iface); continue; }
		Runtime::CreateHook((LPVOID)p, (LPVOID)r.hook, (void**)r.base);
	}
}

